input.command:
cat >> solver.mjs <<'EOF'

// ---------- tick ----------

const EMPTY_OUT = (subject, carry) => ({
  decisions: { subject, constitution: { pins: {} } },
  effects: [],
  obligations: { upsert: [], cancel: [] },
  humanTasks: [],
  carry,
});

export function createSolver() {
  return {
    id: 'solver',
    tick(input, ctx) {
      const carry = input.carry || { order: null };
      const events = input.events || [];
      const out = EMPTY_OUT(carry.order ? carry.order.orderId : null, carry);
      const placed = events.find((e) => e.type === 'message.received' && e.payload && e.payload.orderId && e.payload.items);
      if (placed && !carry.order) {
        return intake(placed, input, ctx, out);
      }
      out.carry = carry;
      return out;
    },
  };
}

function intake(ev, input, ctx, out) {
  const p = ev.payload;
  const orderId = normaliseOrderId(p.orderId);
  const placedAt = ev.at;
  const edition = editionFor(ctx.files, placedAt);
  const catalog = parseJsonFile(ctx.files, 'master/catalog.json') || {};
  const fees = edition ? rulebookTable(ctx.files, edition, 'shipping-fees') || {} : {};
  const policy = edition ? rulebookTable(ctx.files, edition, 'policy') || {} : {};
  const alloc = ctx.query ? null : null;
  void alloc;
  const pin = constitutionInForce(ctx.files, placedAt);
  const carry = {
    order: { orderId, customerId: p.customerId, placedAt, currency: p.currency, edition, pinHash: pin ? pin.hash : null, status: 'intake' },
    policy,
    fees,
    catalog,
  };
  out.decisions.subject = orderId;
  out.decisions.constitution = { pins: { [orderId]: pin ? pin.hash : null } };
  out.carry = carry;
  return out;
}
EOF
node -e "import('./solver.mjs').then(m=>console.log(Object.keys(m)))"

