// A message that starts an instance without an order of ours: customer actions and carrier reports
// belong to the open case of their order (merge), or nothing (S11: no order yet, or no order at all).
function startOther(input, events, ctx, out) {
  const ca = events.find((e) => e.type === 'customer.action' || (e.payload && e.payload.orderRef && e.payload.action));
  const cr = events.find((e) => e.type === 'carrier.status' || (e.payload && e.payload.fulfilmentRef && e.payload.code !== undefined));
  let orderId = null;
  if (ca) {
    orderId = normaliseOrderId(ca.payload.orderRef);
  } else if (cr) {
    const rows = ctx.query('orders.fulfilments', { where: { fulfilmentId: cr.payload.fulfilmentRef }, limit: 1 });
    orderId = rows && rows.length ? rows[0].orderId : null;
  }
  if (orderId) {
    const others = ctx.instances({ subject: orderId }).filter((i) => i.instance !== input.instance);
    if (others.length) out.merge = { into: others[0].instance };
  }
  out.decisions.subject = null;
  out.close = true;
  out.carry = {};
  return out;
}

// ---------- events ----------

function advance(input, events, ctx, out) {
  const o = out.carry.order;
  o.keys = o.keys || {};
  o.setSt = o.setSt || {};
  o.notes = o.notes || {};
  for (const ev of events) {
    if (ev.type === 'effect.result') onResult(ev, o, ctx);
    else if (ev.type === 'humanTask.answered') onAnswer(ev, o);
    else if (ev.type === 'humanTask.answerRejected' || ev.type === 'humanTask.timeout' || ev.type === 'humanTask.withdrawn') onTaskLost(ev, o);
    else if (ev.type === 'timer.fired') onTimer(ev, o);
    else if (ev.type === 'customer.action' || (ev.payload && ev.payload.orderRef && ev.payload.action)) onCustomerAction(ev, o, ctx);
    else if (ev.type === 'carrier.status' || (ev.payload && ev.payload.fulfilmentRef && ev.payload.code !== undefined)) onCarrier(ev, o, ctx);
  }
  drive(input, o, ctx, out);
  out.carry = out.carry || {};
  return out;
}

// Effect results: fact updates only; the driver decides what follows.
function onResult(ev, o, ctx) {
  const pl = ev.payload || {};
  if (pl.system === 'inventory' && pl.op === 'allocate') return; // handled at intake (below)
  if (pl.system === 'fraud' && pl.op === 'check') {
    if (pl.status === 'ok') o.verdict = (resultOf(pl) || {}).verdict || null;
    return;
  }
  if (pl.key == null) return;
  const k = o.keys[pl.key];
  if (!k) return;
  const perm = pl.error && pl.error.retryable === false;
  const code = pl.error ? (pl.error.code || pl.error) : null;
  if (k.kind === 'res') {
    if (pl.status === 'ok' || (Array.isArray(pl.items) && pl.items.some((x) => x.key === pl.key && x.status === 'ok'))) k.state = 'ok';
    else k.state = 'err';
    k.err = code;
    if (k.state === 'err' && !perm && ['invalid-args', 'field-renamed'].includes(code)) k.state = 'retry';
  } else if (pl.status === 'ok') {
    k.state = 'ok';
  } else if (pl.status === 'error' || pl.status === 'partial') {
    k.state = 'err';
    k.err = code;
    if (code === 'already-collected') k.state = 'collected';
  } else if (pl.status === 'unknown') {
    k.state = 'unknown';
  }
  // Unknown outcomes are resolved with status(key) (S2) by the driver.
  if (k.kind === 'shp' && k.state === 'err' && perm) k.permFail = true;
  if (k.kind === 'chg' && k.state === 'err' && (code === 'card-declined' || perm)) k.permFail = true;
  if (k.kind === 'res' && k.state === 'err' && perm) k.permFail = true;
}

// A customer action counts only in the waiting period (R3.2) or while processing (R6.2).
function onCustomerAction(ev, o, ctx) {
  const p = ev.payload || {};
  if (normaliseOrderId(p.orderRef) !== o.orderId || o.ended) return;
  const counted = { at: ev.at, action: p.action, enteredBy: p.enteredBy || null, source: 'ca' };
  o.actions = o.actions || [];
  o.actions.push(counted);
  if (p.enteredBy) o.enteredBy = [...(o.enteredBy || []), p.enteredBy];
  o.pendingCa = o.pendingCa || [];
  o.pendingCa.push({ at: ev.at, action: p.action });
}

// Carrier report (R4.4): collected/delivered/collectionFailed; collection proofs feed R6.2 (S7).
function onCarrier(ev, o, ctx) {
  const p = ev.payload || {};
  const f = o.fulfilments[p.fulfilmentRef];
  if (!f) return;
  const meaning = carrierMeaning(ctx, o, p.code);
  if (f.done) return;
  f.reports = f.reports || [];
  f.reports.push({ meaning, at: p.reportedAt, delivered: ev.at });
  if (meaning === 'collected' || meaning === 'inTransit' || meaning === 'delivered') {
    if (p.reportedAt <= ev.at) f.proven = true;
  }
  if (meaning === 'collected' || meaning === 'delivered') f.collected = true;
  if (meaning === 'collectionFailed') f.collectionFailed = true;
  if (meaning === 'delivered') f.delivered = true;
  f.pendingAt = f.pendingAt || {};
  f.pendingAt[meaning] = ev.at;
}

function onAnswer(ev, o) {
  const p = ev.payload || {};
  const t = o.tasks && o.tasks[ev.payload.taskId || p.id] ;
  void t;
  o.answers = o.answers || [];
  o.answers.push({ taskId: p.taskId || p.id, at: ev.at, answer: p.answer, user: p.user });
}

function onTaskLost(ev, o) {
  o.lost = o.lost || [];
  o.lost.push(ev.payload && (ev.payload.taskId || ev.payload.id));
}

function onTimer(ev, o) {
  o.fired = o.fired || {};
  o.fired[ev.payload.obligationId] = ev.at;
}
